import rawData from './game-data.json'
import type { GameData, MapIcon } from './types'

/** Generated by `npm run data`; shape is guaranteed by scripts/fetch-data.ts. */
export const gameData = rawData as GameData

const CDN = 'https://ddragon.leagueoflegends.com/cdn'

export const championIconUrl = (image: string): string =>
  `${CDN}/${gameData.patch}/img/champion/${image}`

export const championSplashUrl = (championId: string): string =>
  `${CDN}/img/champion/splash/${championId}_0.jpg`

export const itemIconUrl = (image: string): string => `${CDN}/${gameData.patch}/img/item/${image}`

export const summonersRiftMapUrl = `${CDN}/${gameData.patch}/img/map/map11.png`

/** Ranked emblems are saved to public/ranks/ by `npm run data`. */
export const rankEmblemUrl = (tier: string): string => `${import.meta.env.BASE_URL}ranks/${tier.toLowerCase()}.png`

/** League minimap icons are saved to public/icons/ by `npm run data`. */
export const mapIconUrl = (icon: MapIcon): string => `${import.meta.env.BASE_URL}icons/${icon}.png`
